def _fetch(self, uri, sub_domain=False):
        """
        Send a HEAD request to URL and print response code if it's not in ignored_error_codes
        :param uri: URI to fuzz
        :param sub_domain: If True, build destination URL with {URL}.{HOST} else {HOST}/{URL}
        """
        if sub_domain:
            destination = '{0}.{1}'.format(uri, self.host)
        else:
            destination = '{0}/{1}'.format(self.host, uri)

        try:
            response = requests.head(destination, timeout=self.timeout)
        except requests.exceptions.Timeout:
            self.logger.log(logging.INFO, 'Request timed out')
            return
        except requests.exceptions.ConnectionError:
            self.logger.log(logging.INFO, 'Connection error')
            return
        except requests.exceptions.RequestException:
            self.logger.log(logging.INFO, 'Request error')
            return

        if response.status_code not in self.ignored_error_codes:
            self.logger.log(logging.INFO, 'Response code: {0}'.format(response.status_code))

